TABLETS_PER_FILL_90_DAY = 90
TABLETS_PER_FILL_100_DAY = 100
SWITCH_THRESHOLD_USD = 16000

USD_FIELDS = {
    'price_per_1000_tablets_usd',
    'vial_price_usd',
    'reimbursement_per_fill_300_patients_usd',
    'annual_drug_cost_90_day_usd',
    'annual_drug_cost_100_day_usd',
    'annual_supply_cost_90_day_usd',
    'annual_supply_cost_100_day_usd',
    'annual_reimbursement_90_day_usd',
    'annual_reimbursement_100_day_usd',
    'annual_revenue_90_day_usd',
    'annual_revenue_100_day_usd',
    'annual_revenue_difference_100_minus_90_usd',
    'total_annual_revenue_90_day_usd',
    'total_annual_revenue_100_day_usd',
    'total_annual_revenue_difference_100_minus_90_usd',
    'absolute_total_revenue_difference_usd',
}


class CurrencyEncoder(json.JSONEncoder):
    def iterencode(self, obj, _one_shot=False):
        markers = {} if self.check_circular else None
        return self._iterencode_value(obj, markers, 0)

    def _iterencode_value(self, value, markers, level):
        if isinstance(value, dict):
            yield from self._iterencode_dict(value, markers, level)
        elif isinstance(value, list):
            yield from self._iterencode_list(value, markers, level)
        elif isinstance(value, str):
            yield json.encoder.encode_basestring(value)
        elif isinstance(value, bool):
            yield 'true' if value else 'false'
        elif value is None:
            yield 'null'
        elif isinstance(value, int):
            yield str(value)
        elif isinstance(value, Decimal):
            yield format(value, '.2f')
        elif isinstance(value, float):
            yield format(value, '.2f')
        else:
            yield from super().iterencode(value)

    def _iterencode_dict(self, value, markers, level):
        if markers is not None:
            markerid = id(value)
            if markerid in markers:
                raise ValueError('Circular reference detected')
            markers[markerid] = value

        items = list(value.items())
        if not items:
            yield '{}'
        else:
            yield '{'
            newline_indent = '\n' + ' ' * (self.indent * (level + 1))
            item_separator = self.item_separator + newline_indent
            yield newline_indent
            first = True
            for key, item_value in items:
                if not isinstance(key, str):
                    key = str(key)
                if first:
                    first = False
                else:
                    yield item_separator
                yield json.encoder.encode_basestring(key)
                yield self.key_separator
                yield from self._iterencode_value(item_value, markers, level + 1)
            yield '\n' + ' ' * (self.indent * level)
            yield '}'

        if markers is not None:
            del markers[markerid]

    def _iterencode_list(self, value, markers, level):
        if markers is not None:
            markerid = id(value)
            if markerid in markers:
                raise ValueError('Circular reference detected')
            markers[markerid] = value

        if not value:
            yield '[]'
        else:
            yield '['
            newline_indent = '\n' + ' ' * (self.indent * (level + 1))
            item_separator = self.item_separator + newline_indent
            yield newline_indent
            first = True
            for item in value:
                if first:
                    first = False
                else:
                    yield item_separator
                yield from self._iterencode_value(item, markers, level + 1)
            yield '\n' + ' ' * (self.indent * level)
            yield ']'

        if markers is not None:
            del markers[markerid]

